 "content": "def transform(grid):
    """Project each solid 3x3 color block along its center row and column."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rays = [[set() for _ in range(w)] for _ in range(h)]

    # Locate uniform 3x3 blocks (the structured objects).
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                blocks.append((r + 1, c + 1, color))

    for cr, cc, color in blocks:
        for x in range(w):
            rays[cr][x].add(color)
        for y in range(h):
            rays[y][cc].add(color)

    for r in range(h):
        for c in range(w):
            if len(rays[r][c]) == 1:
                out[r][c] = next(iter(rays[r][c]))
            elif len(rays[r][c]) > 1:
                out[r][c] = 0
    return out
